INSERT INTO research_cases (case_id, title, simulated_content, verified_label, label_basis, difficulty, category) VALUES
('c0000000000000000000000000000001','假中獎通知','恭喜您抽中最新款手機！請於今天內點擊 http://gift-prize.top 填寫收件地址，並支付運費 99 元完成領獎。','scam','中獎通知卻要求先付運費、可疑網域、時間壓力，為常見假中獎話術（團隊自行撰寫之模擬案例）。','easy','假中獎'),
('c0000000000000000000000000000002','假冒同學借錢','嗨！我是你國中同學啦，我換 LINE 了。最近很急需要用錢，可以先轉帳 5000 借我嗎？明天就還你，別告訴別人喔。','scam','自稱熟人換新帳號、急迫借錢且要求保密，未經原管道確認身分（模擬案例）。','easy','假冒親友'),
('c0000000000000000000000000000003','學校社團公告','【學務處公告】本週五第七節社團活動改至體育館舉行，請各社團幹部提前 10 分鐘到場佈置，謝謝配合。','legit','一般校內公告，未要求付款、個資或點擊連結（模擬案例）。','easy','正常通知'),
('c0000000000000000000000000000004','二手交易假認證','我這邊用賣貨便出貨，你下單後客服會傳連結給你做「實名認證」，要輸入網銀帳號密碼才能完成交易喔。','scam','交易平台不會要求買家輸入網銀帳密做認證，屬假客服認證話術（模擬案例）。','medium','網路購物'),
('c0000000000000000000000000000005','購物平台出貨通知','【好物網】您的訂單已出貨，可至 App 內「我的訂單」查看物流進度。本訊息不含任何連結，請勿回覆。','legit','虛構平台的出貨通知，未要求付款或個資，並引導使用官方 App 查詢（模擬案例）。','medium','正常通知'),
('c0000000000000000000000000000006','投資群組帶單','加入我們的股票分析群，老師每天帶單，上個月學員平均獲利 30%，名額有限，快加賴 @stock888 領取飆股。','scam','保證高獲利、名額壓力與導流私人群組，為常見投資詐騙特徵（模擬案例）。','medium','假投資'),
('c0000000000000000000000000000007','包裹地址補件','您好，您的包裹因地址不完整暫時無法投遞，請於 48 小時內回覆完整地址與收件人生日，以便重新安排配送。','scam','物流業者不需生日即可配送；以補件為由蒐集個資，常用於後續詐騙（模擬案例）。','hard','假物流'),
('c0000000000000000000000000000008','班級校外教學收費','同學好，下週二校外教學費用 350 元，請於週五前交給班級總務，收據會由學務處統一開立。','legit','雖然涉及付款，但為面對面繳交給已知同學，並有學校開立收據，屬正常校務（模擬案例）。','hard','正常通知'),
('c0000000000000000000000000000009','平台安全提醒','【好物網】提醒您：我們不會以電話或訊息要求您提供驗證碼或密碼。如有疑問，請由 App 內客服中心聯繫。','legit','內容提到驗證碼，但是在提醒使用者不要提供，並引導至官方管道（模擬案例）。','hard','正常通知');
INSERT INTO pattern_dataset (pattern_id, scam_category, psychological_trigger, risk_indicators, prevention_method, evidence_source, source_license) VALUES
('p0000000000000000000000000000001','假冒客服解除分期','權威＋恐懼','自稱客服、誤設分期、要求操作 ATM 或網銀','掛斷後自行撥打官方客服電話確認；ATM 無法解除分期。','研究團隊自行整理（待人工審查）','團隊自製內容'),
('p0000000000000000000000000000002','假投資','貪婪＋從眾','保證獲利、老師帶單、加入私人群組','合法投資不保證獲利；不加入不明投資群組。','研究團隊自行整理（待人工審查）','團隊自製內容'),
('p0000000000000000000000000000003','假網拍認證','權威＋急迫','要求點擊認證連結並輸入網銀帳密','只在官方 App 內完成交易，不在外部連結輸入帳密。','研究團隊自行整理（待人工審查）','團隊自製內容'),
('p0000000000000000000000000000004','假冒親友借錢','信任＋情感','換新帳號、急需用錢、要求保密','用原本電話或當面確認身分。','研究團隊自行整理（待人工審查）','團隊自製內容'),
('p0000000000000000000000000000005','求職打工詐騙','貪婪＋缺乏經驗','高薪輕鬆、要求提供提款卡或帳戶','不出租、出借帳戶與提款卡，避免成為人頭帳戶。','研究團隊自行整理（待人工審查）','團隊自製內容');
